import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"One-click dependencies","description":"Linux script installs PostgreSQL via apt or yum/dnf and optionally Redis. It does not download the KiriVers binary.","frontmatter":{"title":"One-click dependencies","description":"Linux script installs PostgreSQL via apt or yum/dnf and optionally Redis. It does not download the KiriVers binary."},"headers":[],"relativePath":"en/guide/install/one-click.md","filePath":"en/guide/install/one-click.md","lastUpdated":1790057721000}`),a={name:`en/guide/install/one-click.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="one-click-dependencies" tabindex="-1">One-click dependencies <a class="header-anchor" href="#one-click-dependencies" aria-label="Permalink to “One-click dependencies”">​</a></h1><p><a href="https://github.com/Kirizu-Official/KiriVers/blob/main/scripts/install-deps.sh" target="_blank" rel="noreferrer"><code>scripts/install-deps.sh</code></a> installs PostgreSQL on Linux with <strong>apt or yum/dnf</strong>, and asks whether to install <strong>Redis</strong> from the same package manager.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to “What it does”">​</a></h2><table tabindex="0"><thead><tr><th>Does</th><th>Does not</th></tr></thead><tbody><tr><td>Install PostgreSQL as root/sudo and try to enable the service</td><td>Download any KiriVers package</td></tr><tr><td>Optionally install Redis after a prompt</td><td>Call Docker</td></tr><tr><td>Print the next step: open the manual install page, then get the package for your platform from GitHub Releases (<code>KiriVers-&lt;OS&gt;-&lt;Arch&gt;-&lt;sha6&gt;.zip</code>)</td><td>Support Windows</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Windows</p><p>Do not run this script on Windows. Use <a href="/en/guide/install/manual">manual install</a>.</p></div><h2 id="redis-choice" tabindex="-1">Redis choice <a class="header-anchor" href="#redis-choice" aria-label="Permalink to “Redis choice”">​</a></h2><ul><li><strong>Skip</strong>: single node, modest traffic. Keep <code>cache.driver=memory</code> (default).</li><li><strong>Install</strong>: multiple KiriVers processes, or you will set <code>cache.driver=redis</code>. Startup <strong>must</strong> Ping successfully or the process will not listen. A runtime Redis outage falls back to in-process memory and reconnects; the process does <strong>not</strong> exit immediately. See <a href="/en/guide/config/cache">Cache and Redis</a>.</li></ul><h2 id="supported-systems" tabindex="-1">Supported systems <a class="header-anchor" href="#supported-systems" aria-label="Permalink to “Supported systems”">​</a></h2><p>Linux with <code>apt-get</code> or <code>yum</code>/<code>dnf</code>, run as root. macOS and distros without those managers: the script exits 1; use manual install or Docker.</p><h2 id="procedure" tabindex="-1">Procedure <a class="header-anchor" href="#procedure" aria-label="Permalink to “Procedure”">​</a></h2><ol><li>Run as root (replace the URL if you cloned the repo):</li></ol><div class="vp-code-group"><div class="tabs"><input type="radio" name="group-83" id="tab-84" checked><label data-title="curl" for="tab-84">curl</label><input type="radio" name="group-83" id="tab-85"><label data-title="wget" for="tab-85">wget</label><input type="radio" name="group-83" id="tab-86"><label data-title="local" for="tab-86">local</label></div><div class="blocks"><div class="language-bash active line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/Kirizu-Official/KiriVers/main/scripts/install-deps.sh</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-bash line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wget</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -qO-</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/Kirizu-Official/KiriVers/main/scripts/install-deps.sh</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-bash line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/install-deps.sh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></div></div><ol start="2"><li>Enter the sudo password if prompted.</li><li>Answer the Redis prompt: <code>y</code> to install, Enter to skip.</li><li>On success, stdout states PostgreSQL is installed and points at the manual install page for the KiriVers package. Note the default database port (usually <code>5432</code>) and the distro postgres user policy.</li></ol><details class="details custom-block"><summary>What success stdout contains</summary><p>The script prints that PostgreSQL is installed and points at GitHub Releases for the package, then the manual install page (copy three YAML files, create an admin, start the process). If Redis was installed, it notes that a single process may keep <code>cache.driver=memory</code>; multiple processes or <code>cache.driver=redis</code> require a successful startup Ping.</p></details><div class="tip custom-block"><p class="custom-block-title">Releases ships zip archives</p><p>The script only installs databases; it never touches KiriVers. When you do fetch the server, pick <code>KiriVers-&lt;OS&gt;-&lt;Arch&gt;-&lt;sha6&gt;.zip</code> on the Release page by <strong>prefix</strong> (the trailing six hex chars are the first six of the packed binary&#39;s SHA-256, so the name changes every release). Unpacking gives you <code>kirivers-&lt;os&gt;-&lt;arch&gt;</code> (<code>.exe</code> on Windows). See <a href="/en/guide/install/manual">manual install</a>.</p></div><h2 id="failures" tabindex="-1">Failures <a class="header-anchor" href="#failures" aria-label="Permalink to “Failures”">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Action</th></tr></thead><tbody><tr><td>Not root</td><td>Retry with <code>sudo</code></td></tr><tr><td>No apt/yum/dnf</td><td>Exit 1; use manual install or Docker. Missing Docker is <strong>not</strong> a failure of this script</td></tr><tr><td>Port <code>5432</code> in use</td><td>Stop the old PostgreSQL or change the DSN port</td></tr><tr><td>Distro repo has no postgresql package</td><td>Enable the distro module stream / official PostgreSQL repo, or install manually</td></tr></tbody></table><p>Next: <a href="/en/guide/install/manual">manual install</a>.</p>`,18)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};